// Kind is what a run does. It decides the icon, the footer verb and — at
// poste 8 — whether the run can be cancelled at all.
type Kind string

const (
	KindScan   Kind = "scan"
	KindSync   Kind = "sync"
	KindClone  Kind = "clone"
	KindPull   Kind = "pull"
	KindCreate Kind = "create"
	KindDelete Kind = "delete"
)

// Kinds returns every declared kind, in the order a view should offer them.
// It exists to be walked by a test: a kind without an icon or without a verb
// is a hole that only shows up on the screen that needed it.
func Kinds() []Kind {
	return []Kind{KindScan, KindSync, KindClone, KindPull, KindCreate, KindDelete}
}

// Cancellable reports whether stopping a run of this kind leaves the machine in
// a state the user asked for.
//
// The queue always stops — nothing further starts, whatever the kind — so this
// answers the narrower question of whether work already in flight can be cut.
// It is the table from D7, kept next to the kinds so a new kind cannot be added
// without answering it:
//
//	scan    yes  Trivy and Gitleaks read; cutting leaves nothing behind
//	pull    yes  a docker pull resumes by layer
//	sync    no   the queue stops, a fast-forward in flight is waited out
//	clone   no   a cut git clone leaves half a repository on disk
//	create  no   a request already sent cannot be un-sent
//	delete  no   half deleted is worse than deleted
//
// A run whose kind answers no still accepts Cancel: the queue stopping is worth
// having on its own. What the answer gates is whether a view offers the key on
// a single item (Rule 130 — greyed, with a named reason, never silent).
func (k Kind) Cancellable() bool {
	return k == KindScan || k == KindPull
}

// Verb is what a kind is called while it runs — present participle, English US
// (Rule 129). It lives here rather than in a view because two now say it: the
// footer of the view that launched the run, and the `:jobs` list.
//

	defer stop()

	// io.EOF is how a stdio server ends: the client closed the pipe, which is
	// the ordinary shutdown and not a failure. Reporting it as one gives an exit
	// code that some clients surface as a crash for a server that worked. The
	// sentinel is checked rather than the message because the SDK's own
	// ErrServerClosing lives in an internal package and cannot be compared to.
	err = mcpserver.Serve(ctx, &mcpserver.Env{Config: cfg, Context: name})
	if err != nil && !errors.Is(err, io.EOF) && ctx.Err() == nil {
		fmt.Fprintf(os.Stderr, "dk mcp: %v\n", err)
		return 1
	}
	return 0
}

func runTUI() {
	// Forcer TrueColor si Windows Terminal est détecté (WSL ne propage pas COLORTERM)
	if os.Getenv("WT_SESSION") != "" && os.Getenv("COLORTERM") == "" {
		_ = os.Setenv("COLORTERM", "truecolor")
	}

	// Charger la configuration
	cfg, err := config.Load()
	if err != nil {
		fmt.Printf("Error loading config: %v\n", err)
		fmt.Println("Using default configuration.")
		cfg = config.Default()
	}

	// Créer le répertoire de config s'il n'existe pas
	if err := config.EnsureConfigDir(); err != nil {
		fmt.Printf("Warning: Could not create config directory: %v\n", err)
	}

	// Toujours activer le logging dans un fichier pour éviter de polluer l'interface TUI
	logFile, err := tea.LogToFile(cfg.App.LogFile, "debug")
	if err != nil {
		fmt.Printf("Warning: Could not create log file: %v\n", err)
	} else {
		defer func() { _ = logFile.Close() }()
		log.Printf("=== DevDesk Started ===")
		log.Printf("Config loaded from context: %s", getCurrentContextName())
		log.Printf("Log file: %s", cfg.App.LogFile)
		log.Printf("DEBUG mode: %v", len(os.Getenv("DEBUG")) > 0)
	}

	// Charger et appliquer le thème sauvegardé
	if cfg.App.Theme != "" && cfg.App.Theme != "dark" {
		t, err := theme.LoadTheme(cfg.App.Theme)
		if err != nil {
			log.Printf("Warning: Could not load theme '%s': %v, using default", cfg.App.Theme, err)
		} else {
			theme.ApplyTheme(t)
			theme.CurrentThemeName = cfg.App.Theme
			log.Printf("Theme loaded: %s", cfg.App.Theme)
		}
	}

	// Créer l'application avec le router
	m := app.New(cfg)

	// Options du programme Bubble Tea
	opts := []tea.ProgramOption{
		tea.WithAltScreen(), // Mode plein écran
	}

	// Lancer le programme Bubble Tea
	p := tea.NewProgram(m, opts...)

	if _, err := p.Run(); err != nil {
		fmt.Printf("Error running application: %v\n", err)
		os.Exit(1)
	}
}

