			}
			if !m.scanningImage(name) {
				queue = append(queue, imageScanJob{Name: name, Target: target})
			}
		}
		if len(queue) == 0 {
			return m, jobs.Refuse(msg.Invocation, reasonImageScanned)
		}
	}

	return m, jobs.WithInvocation(msg.Invocation, jobs.Start(
