func TestAnActionIsAnsweredWithTheIDOfItsOwnRun(t *testing.T) {
	a := router(t, &bareView{})

	reply := make(chan mcpStartReply, 1)
	a.pendingInvocations = map[invocationID]chan mcpStartReply{"7": reply}

